mapper.select:
SELECT
e.is_deleted = 0
AND e.student_id = #{studentId}
AND e.training_class_id = #{trainingClassId}
AND e.status = #{status}
AND (e.enrollment_no LIKE CONCAT('%', #{keyword}, '%') OR tc.class_code LIKE CONCAT('%', #{keyword}, '%') OR tc.class_name LIKE CONCAT('%', #{keyword}, '%') OR c.course_name LIKE CONCAT('%', #{keyword}, '%') OR student.user_name LIKE CONCAT('%', #{keyword}, '%') OR e.snapshot_real_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY e.create_time DESC, e.id DESC
